import{c as d,Q as r,j as e,m as a}from"./chunks/framework.rWdQudnF.js";const c=JSON.parse('{"title":"输入输出技术和总线","description":"","frontmatter":{"title":"输入输出技术和总线"},"headers":[],"relativePath":"综合知识/系统基础/计算机组成/输入输出技术和总线.md","filePath":"综合知识/系统基础/计算机组成/输入输出技术和总线.md","lastUpdated":null}'),o={name:"综合知识/系统基础/计算机组成/输入输出技术和总线.md"};function n(s,t,l,h,i,g){return r(),e("div",null,[...t[0]||(t[0]=[a('<h3 id="输入输出技术" tabindex="-1">输入输出技术 <a class="header-anchor" href="#输入输出技术" aria-label="Permalink to &quot;输入输出技术&quot;">​</a></h3><h4 id="i-o-编址方式" tabindex="-1">I/O 编址方式 <a class="header-anchor" href="#i-o-编址方式" aria-label="Permalink to &quot;I/O 编址方式&quot;">​</a></h4><table tabindex="0"><thead><tr><th>对比</th><th>独立编址（I/O 映射）</th><th>统一编址（内存映射）</th></tr></thead><tbody><tr><td>地址空间</td><td>内存+I/O 两个独立空间</td><td>统一地址空间</td></tr><tr><td>指令</td><td>专用 I/O 指令（IN/OUT）</td><td>通用内存访问指令</td></tr><tr><td>优点</td><td>易辨认、互不干扰</td><td>指令丰富灵活</td></tr><tr><td>缺点</td><td>指令功能有限</td><td>内存地址不连续</td></tr><tr><td>典型</td><td>Intel x86</td><td>ARM、嵌入式</td></tr></tbody></table><h4 id="数据交互三种方式" tabindex="-1">数据交互三种方式 <a class="header-anchor" href="#数据交互三种方式" aria-label="Permalink to &quot;数据交互三种方式&quot;">​</a></h4><table tabindex="0"><thead><tr><th>方式</th><th style="text-align:center;">CPU 参与度</th><th style="text-align:center;">效率</th><th>机制</th></tr></thead><tbody><tr><td><strong>程序查询</strong></td><td style="text-align:center;">全程参与</td><td style="text-align:center;">最低</td><td>CPU 主动轮询设备状态</td></tr><tr><td><strong>程序中断</strong></td><td style="text-align:center;">传输后处理</td><td style="text-align:center;">中</td><td>设备就绪后<strong>主动通知</strong>CPU</td></tr><tr><td><strong>DMA</strong></td><td style="text-align:center;">仅初始化</td><td style="text-align:center;"><strong>最高</strong></td><td>DMA 控制器接管总线，直接设备↔内存</td></tr></tbody></table><p><strong>中断 vs DMA 响应时机：</strong></p><ul><li>CPU 响应<strong>中断</strong>请求：在<strong>一条指令执行结束时</strong></li><li>CPU 响应<strong>DMA</strong>请求：在一个<strong>总线周期结束后</strong></li></ul><blockquote><p>DMA 方式数据传输整个过程由 DMA 控制器完成，<strong>不需要 CPU 执行程序指令来传送数据</strong>。</p></blockquote><h3 id="总线" tabindex="-1">总线 <a class="header-anchor" href="#总线" aria-label="Permalink to &quot;总线&quot;">​</a></h3><h4 id="总线结构" tabindex="-1">总线结构 <a class="header-anchor" href="#总线结构" aria-label="Permalink to &quot;总线结构&quot;">​</a></h4><table tabindex="0"><thead><tr><th>层级</th><th>作用域</th><th>关键特征</th></tr></thead><tbody><tr><td><strong>内部总线</strong>（片内）</td><td>芯片内部</td><td>高带宽、低延迟、不对外开放</td></tr><tr><td><strong>系统总线</strong>（板级）</td><td>主板+扩展槽</td><td>决定内存最大容量，三总线并行</td></tr><tr><td><strong>外部总线</strong>（设备级）</td><td>机箱外设</td><td>热插拔、即插即用</td></tr></tbody></table><p><strong>系统总线&quot;三驾马车&quot;：</strong></p><table tabindex="0"><thead><tr><th>总线</th><th style="text-align:center;">方向</th><th>作用</th></tr></thead><tbody><tr><td><strong>数据总线</strong></td><td style="text-align:center;">双向</td><td>传输数据，宽度 = 字长倍数</td></tr><tr><td><strong>地址总线</strong></td><td style="text-align:center;">单向</td><td>传输地址，宽度决定<strong>寻址空间</strong></td></tr><tr><td><strong>控制总线</strong></td><td style="text-align:center;">—</td><td>传输控制信号（读/写/中断/时钟等）</td></tr></tbody></table><h4 id="串行总线-vs-并行总线" tabindex="-1">串行总线 vs 并行总线 <a class="header-anchor" href="#串行总线-vs-并行总线" aria-label="Permalink to &quot;串行总线 vs 并行总线&quot;">​</a></h4><blockquote><p>🎯 一句话结论：<strong>并行总线适合短距离高速传输，串行总线适合长距离</strong>；PCI 是并行总线，USB/SATA/RapidIO/PCIe 是串行总线。</p></blockquote><table tabindex="0"><thead><tr><th>对比</th><th>串行总线</th><th>并行总线</th></tr></thead><tbody><tr><td>传输方式</td><td>逐位（bit）串行发送</td><td>多根数据线同时发送多位</td></tr><tr><td>代表接口</td><td>USB, SATA, RS-232, RapidIO, PCIe</td><td><strong>PCI</strong>, IDE(PATA), LPT</td></tr><tr><td>传输距离</td><td>适宜<strong>长距离</strong></td><td>适宜<strong>短距离</strong></td></tr><tr><td>信号同步</td><td>嵌入时钟或异步</td><td>需同时到达，高频难度大</td></tr><tr><td>波特率</td><td>初始化时预定义，使用中不变</td><td>—</td></tr></tbody></table><blockquote><p>⚠️ 易混淆：<strong>PCI ≠ PCIe</strong>。PCI 是并行总线，PCI Express (PCIe) 是串行总线。考题常把 PCI 混入&quot;以下属于串行总线的是&quot;选项中。</p></blockquote><h4 id="串行总线波特率" tabindex="-1">串行总线波特率 <a class="header-anchor" href="#串行总线波特率" aria-label="Permalink to &quot;串行总线波特率&quot;">​</a></h4><blockquote><p>🎯 一句话结论：<strong>串行总线波特率在总线初始化时预先定义，使用中不可改变</strong>。</p></blockquote><ul><li>波特率（Baud Rate）= 每秒传输的信号单元数（不同于比特率）</li><li>常见标准波特率：9600, 19200, 38400, 115200 等</li><li>并非所有串行总线都是全双工（I²C 是半双工/同步串行）</li><li>数据正确性依赖校验码（奇偶校验、CRC）而非仅靠纠错码</li></ul>',20)])])}const u=d(o,[["render",n]]);export{c as __pageData,u as default};
